for odp in Tak n moze; do
  case "$odp" in
    [tT]|[tT]ak|[yY]|[yY]es) echo "$odp -> zgoda" ;;
    [nN]|[nN]ie|[nN]o)       echo "$odp -> odmowa" ;;
    *)                       echo "$odp -> nie rozumiem" ;;
  esac
done

for plik in raport.csv sklep.jar kopia.sql.gz notatki.txt; do
  case "$plik" in
    *.csv)            typ="dane CSV" ;;
    *.jar|*.war)      typ="artefakt Javy" ;;
    *.gz|*.zst|*.xz)  typ="archiwum skompresowane" ;;
    *)                typ="inny" ;;
  esac
  echo "$plik -> $typ"
done

for godzina in 03 08 13 19; do
  case "$godzina" in
    0[0-6])          echo "$godzina: noc - okno serwisowe" ;;
    0[7-9]|1[0-7])   echo "$godzina: godziny pracy" ;;
    *)               echo "$godzina: wieczor" ;;
  esac
done

cat > sprawdz-kopie.sh <<'KONIEC'
#!/bin/bash
for plik in "$(dirname "$(readlink -f "$0")")"/kopie/*; do
    case "$plik" in
        *.sql.gz)   gunzip -t "$plik" && echo "${plik##*/}: zrzut SQL OK" ;;
        *.gz)       echo "${plik##*/}: archiwum - pomijam" ;;
        *.dump)     [ -s "$plik" ] && echo "${plik##*/}: zrzut niepusty" ;;
        *)          echo "${plik##*/}: nieznany typ" ;;
    esac
done
KONIEC
chmod +x sprawdz-kopie.sh
