cat > lab-ctl.sh <<'KONIEC'
#!/bin/bash
# lab-ctl.sh POLECENIE [PORT] - zarzadzanie aplikacja laboratorium
lab=$(dirname "$(readlink -f "$0")")
pomoc() { echo "Uzycie: lab-ctl.sh {start|stop|status|wersja} [18094|18095]"; }
port=${2:-18094}
case "$port" in
    18094|18095) ;;
    *) echo "BLAD: nieznana instancja '$port'" >&2; pomoc >&2; exit 2 ;;
esac
pidplik="$lab/app-$port.pid"
case "$1" in
    start)
        python3 -m http.server "$port" --bind 127.0.0.1 --directory "$lab/www" > /dev/null 2>&1 &
        echo $! > "$pidplik"; sleep 1; echo "uruchomiono na $port" ;;
    stop)
        kill "$(cat "$pidplik" 2>/dev/null)" 2>/dev/null; rm -f "$pidplik"; echo "zatrzymano $port" ;;
    status|st)
        if [ -f "$pidplik" ] && kill -0 "$(cat "$pidplik")" 2>/dev/null; then echo "$port: dziala"; else echo "$port: zatrzymana"; fi ;;
    wersja|-v|--version)
        curl -s "http://127.0.0.1:$port/info" | grep -o '"version":"[^"]*"' | cut -d'"' -f4 ;;
    -h|--help|"")
        pomoc ;;
    *)
        echo "BLAD: nieznane polecenie '$1'" >&2; pomoc >&2; exit 2 ;;
esac
KONIEC
chmod +x lab-ctl.sh
bash -n lab-ctl.sh && echo "skladnia OK"

